// Preencher apenas no editor local do n8n; não salvar dados pessoais no Git.
// Não incluir senha. Executar manualmente uma vez, sem escritores concorrentes.
const config = {
 spreadsheet_id: '1dRBMU7BH9PLzWjgAjj4VWnLUqpSVIWC6iKQj9URczMo',
 participante_id: 'CONFIGURAR_ID_OWNER',
 pelada_id: 'CONFIGURAR_PELADA_ID_EXISTENTE',
 nome: 'Ricardo',
 apelido: 'Ricardo',
 cpf: 'CONFIGURAR_CPF',
 telefone: 'CONFIGURAR_TELEFONE',
 email: 'CONFIGURAR_EMAIL'
};
const cpf = String(config.cpf).replace(/\D/g, '');
function valid(cpf) {
 if (!/^\d{11}$/.test(cpf) || /^(\d)\1{10}$/.test(cpf)) return false;
 for (let n=9;n<=10;n++) {
  let sum=0; for(let i=0;i<n;i++) sum+=Number(cpf[i])*(n+1-i);
  const rest=sum%11; if(Number(cpf[n]) !== (rest<2?0:11-rest)) return false;
 }
 return true;
}
if(Object.values(config).some(v=>!String(v).trim() || String(v).includes('CONFIGURAR_')) || !valid(cpf) || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(config.email) || !/^\+?[\d ()-]{10,20}$/.test(config.telefone)) throw new Error('Preencha os dados administrativos válidos; nenhum registro foi enviado.');
return [{json:{...config,cpf,email:config.email.trim().toLowerCase()}}];

const cfg = $('Dados do OWNER').first().json;
const rows = $input.first().json.values;
const fields = ["participante_id", "pelada_id", "nome", "apelido", "cpf", "telefone", "email", "categoria", "papel_administrativo", "situacao", "asaas_customer_id", "convidado_por_id", "convidado_por_nome", "criado_em", "atualizado_em", "senha_hash", "token_sessao_hash", "token_expira"];
if(!Array.isArray(rows) || fields.some((f,i)=>rows[0]?.[i]!==f)) throw new Error('Cabeçalhos de JOGADORES incompatíveis; nenhuma gravação.');
const records = rows.slice(1).filter(r=>r.some(v=>String(v).trim())).map(r=>Object.fromEntries(fields.map((f,i)=>[f,String(r[i]??'')])));
const same = records.filter(r=>r.participante_id===cfg.participante_id || (r.pelada_id===cfg.pelada_id && r.cpf.replace(/\D/g,'')===cfg.cpf));
if(same.length) throw new Error('Identidade já cadastrada ou conflitante. Nenhuma alteração; conferir no Sheets antes de repetir.');
if(records.some(r=>r.papel_administrativo.trim().toUpperCase()==='OWNER')) throw new Error('Já existe OWNER. Nenhuma alteração automática de titularidade.');
const now=new Date().toISOString();
const row={...cfg,categoria:'',papel_administrativo:'OWNER',situacao:'ativo',criado_em:now,atualizado_em:now};
return [{json:{values:[fields.map(f=>row[f]??'')]}}];
